import React from 'react';

const DEFAULT_OPTIONS = [
  { value: 'en', label: 'English', shortLabel: 'EN' },
  { value: 'no', label: 'Norsk', shortLabel: 'NO' },
  { value: 'nl', label: 'Nederlands', shortLabel: 'NL' },
  { value: 'is', label: 'Icelandic', shortLabel: 'IS' }
];

const LanguageSelector = ({
  value,
  onChange,
  options = DEFAULT_OPTIONS,
  label = 'Language',
  showLabel = false,
  showIcon = true,
  className = ''
}) => {
  return (
    <label
      className={`flex items-center gap-2 rounded-full border border-white/30 bg-white/10 px-3 py-1 text-sm font-semibold text-white shadow-glass transition hover:bg-white/20 ${className}`.trim()}
    >
      {showIcon && (
        <svg
          aria-hidden="true"
          viewBox="0 0 24 24"
          className="h-4 w-4 text-white"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <circle cx="12" cy="12" r="10" />
          <path d="M2 12h20" />
          <path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z" />
        </svg>
      )}
      <span className="sr-only">{label}</span>
      {showLabel && <span className="text-xs uppercase tracking-[0.2em]">{label}</span>}
      <select
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="bg-transparent text-white focus:outline-none"
        aria-label={label}
      >
        {options.map((option) => (
          <option key={option.value} value={option.value} className="text-slate-900">
            {option.label} ({option.shortLabel})
          </option>
        ))}
      </select>
    </label>
  );
};

export default LanguageSelector;
